/*
 * mtp-args — the CTest case for the semihosting command line.
 * GENERATED by micro-os-scaffold (--micro-test-plus).
 *
 * It checks the transport itself, not a kernel feature: the runner passes
 *
 *   arm semihosting_cmdline mtp-args --output-file <path>
 *
 * (QEMU: -semihosting-config ...,arg=mtp-args,arg=--output-file,arg=<path>;
 * host: the same two process arguments). os_main () must receive them as
 * argc/argv, and mtp_board::run () must parse the same words.
 *
 * The suite is in suite-args.cpp and registers itself, like every other
 * suite. No suite list here.
 */
#include <mtp_board.hpp>

namespace mtp_args
{
  // Written by os_main () before mtp_board::run (); read by suite-args.cpp so
  // the suite can compare what the C runtime delivered with what mtp_board
  // parsed.
  int argc = 0;
  char** argv = nullptr;
} // namespace mtp_args

int
os_main (int argc, char* argv[])
{
  mtp_args::argc = argc;
  mtp_args::argv = argv;
  mtp_board::start ("mtp-args");
#if defined(MTP_HAS_SMP_BOOT) && MTP_HAS_SMP_BOOT
  // "00 - Cores" is registered by the board support for every test on a
  // multi-core board; bring the other cores up as the other starters do.
  mtp_board::release_cores ();
#endif
  return mtp_board::run (argc, argv);
}

#include <mtp_startup.hpp>
